"use client";

import { useState, useEffect } from "react";
import { useFinanceData, useSubmit } from "@/lib/api";
import { TransactionForm } from "@/components/finance/TransactionForm";
import { Empty } from "@/components/finance/Empty";
import { TransactionTable } from "@/components/finance/TransactionTable";
import { CategoryBreakdown } from "@/components/finance/CategoryBreakdown";
import { MonthlyTrend } from "@/components/finance/MonthlyTrend";
import { RecurringList } from "@/components/finance/RecurringList";
import { InsightsPanel } from "@/components/finance/InsightsPanel";

const TrackerPage = () => {
  const [data, setData] = useState<any | null>(null);
  const [error, setError] = useState<any | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await useFinanceData("/tracker");
        setData(response);
      } catch (err) {
        setError(err);
      }
    };

    fetchData();
  }, []);

  if (!data) return <Empty />;

  return (
    <div className="flex flex-col gap-4">
      <TransactionForm />
      <TransactionTable data={data.transactions} />
      <CategoryBreakdown data={data.categories} />
      <MonthlyTrend data={data.trend} />
      <RecurringList data={data.recurring} />
      <InsightsPanel data={data.insights} />
    </div>
  );
};

export default TrackerPage;
